"""Original kidney transplantation chapter: selection, dysfunction and immunology."""
from qbank_authoring import question,ref,finalize
TC=ref('KDIGO Transplant Candidate Guideline, 2020','https://kdigo.org/wp-content/uploads/2026/04/KDIGO-2020-Transplant-Candidate-Guideline.pdf')
TR=ref('KDIGO Transplant Recipient Guideline, 2009','https://kdigo.org/wp-content/uploads/2026/04/KDIGO-2009-Transplant-Recipient-Guideline.pdf')
EA=ref('EAU Guidelines on Renal Transplantation, current online guideline','https://uroweb.org/guidelines/renal-transplantation/chapter/the-guideline')
BA=ref('Banff Foundation: Current Reference Guide to Renal Allograft Classification','https://banfffoundation.org/central-repository-for-banff-classification-resources-3/')
BK=ref('Second International Consensus Guidelines on BK Polyomavirus in Kidney Transplantation, 2024','https://pmc.ncbi.nlm.nih.gov/articles/PMC11335089/')
CM=ref('Fourth International Consensus Guidelines on CMV in Solid Organ Transplantation, 2025','https://pmc.ncbi.nlm.nih.gov/articles/PMC12180710/')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('A transplant-eligible patient has progressive advanced CKD and a potential living donor. What is the preferred planning principle?', 'Early evaluation to enable preemptive living-donor transplantation when feasible',[
 ('Wait until several years of dialysis before referral','This unnecessarily delays evaluation and a possible preemptive option.'),('A living donor eliminates the need for recipient assessment','The full medical and immunological work-up remains necessary.'),('Preemptive transplantation means transplanting regardless of kidney trajectory','Timing still depends on progressive irreversible disease and suitability.')],
 'Prepare before an urgent dialysis start', '**KDIGO recommends referral about 6–12 months before anticipated dialysis to allow evaluation.**',['Living-donor work-up can take substantial time.','Dialysis and access planning may still be needed as a contingency.'], '**Assess donor and recipient safety independently.**',['Discuss benefits, burdens and alternatives.','Use the individual kidney trajectory to plan timing.'],[['Referral','Before anticipated dialysis'],['Preferred feasible option','Preemptive living-donor transplant'],['Contingency','KRT planning if timing changes']],[TC],'clinical_scenario')
q('Which condition generally warrants deferring kidney transplantation until adequately treated?', 'An active uncontrolled infection',[
 ('Older chronological age alone in every otherwise suitable candidate','Age alone should not be a universal exclusion.'),('Stable treated diabetes alone','Diabetes requires risk assessment but is not by itself an absolute exclusion.'),('A remote cured infection without ongoing risk','This does not have the same implication as active uncontrolled infection.')],
 'Immunosuppression can amplify untreated infection', '**Active infection should generally be controlled before transplantation.**',['Some chronic infections have specific managed transplant pathways.','Frailty, comorbidity and expected benefit require integrated assessment.'], '**Treat reversible barriers and reassess eligibility.**',['Avoid blanket exclusion based on one demographic feature.','Coordinate infectious and transplant expertise.'],[['Active uncontrolled infection','Usually defer'],['Managed chronic infection','Specific pathway'],['Age/comorbidity','Integrated risk assessment']],[TC])
q('Why is a history of pregnancy, transfusion or prior transplantation important during recipient immunological assessment?', 'These exposures can produce anti-HLA sensitization',[
 ('They guarantee a negative crossmatch','They can increase donor-reactive antibody risk.'),('They directly determine ABO type','ABO type is inherited rather than acquired through these exposures.'),('They eliminate the need for current antibody testing','Antibody testing is particularly important in sensitized candidates.')],
 'Previous antigen exposure changes compatibility risk', '**Sensitization can restrict suitable donors and increase rejection risk.**',['Antibody specificity and strength need expert interpretation.','A new sensitizing event may require updated testing.'], '**Integrate donor-specific antibody and crossmatch information.**',['A broad sensitization measure is not identical to compatibility with one donor.','Use paired exchange or other specialist strategies where appropriate.'],[['Exposures','Pregnancy/transfusion/prior graft'],['Effect','Possible anti-HLA antibodies'],['Decision','Donor-specific assessment']],[TC])
q('What is the main purpose of a donor-recipient crossmatch?', 'Detecting recipient immune reactivity against donor cells or donor antigens',[
 ('Measuring recipient kidney clearance','This is assessed by renal tests.'),('Proving there is no future possibility of rejection','Rejection can occur despite a negative pretransplant test.'),('Replacing all HLA antibody and clinical assessment','The test is one part of compatibility evaluation.')],
 'Compatibility testing estimates a specific immune risk', '**A positive crossmatch may indicate clinically important donor-reactive antibodies.**',['Test method and antibody context affect interpretation.','Virtual crossmatch uses known donor HLA and recipient antibody data.'], '**Use a specialist interpretation rather than a binary rule detached from method.**',['ABO compatibility is a separate consideration.','Selected incompatible pathways require specific protocols and counseling.'],[['Crossmatch','Donor-specific reactivity'],['Virtual approach','HLA and antibody data'],['Negative result','Does not guarantee no rejection']],[TC,EA])
q('A newly reperfused graft becomes cyanotic and fails immediately with widespread vascular thrombosis. Which immune mechanism is classic for hyperacute rejection?', 'Preformed donor-reactive antibodies causing endothelial injury and thrombosis',[
 ('A de novo slow T-cell response arising only months later','That timing does not explain immediate hyperacute injury.'),('BK viral replication acquired after surgery','BK nephropathy is not an immediate reperfusion event.'),('Chronic calcineurin toxicity','It does not produce this immediate antibody-mediated pattern.')],
 'Pre-existing antibodies can act as soon as blood reaches the graft', '**Anti-HLA or ABO antibodies can trigger severe vascular injury.**',['Modern compatibility assessment makes this uncommon.','Technical arterial or venous thrombosis remains an urgent competing diagnosis.'], '**Obtain immediate transplant surgical assessment.**',['Time-critical vascular evaluation should not be delayed by an assumed immune label.','Pathology and immunology help establish the final cause.'],[['Timing','Minutes to hours'],['Mechanism','Preformed antibody'],['Competing cause','Technical vascular complication']],[EA,BA],'clinical_scenario')
q('A deceased-donor kidney requires dialysis during the first postoperative week. What does the common operational term delayed graft function establish?', 'Early graft dysfunction, not a specific histological diagnosis',[
 ('Acute rejection is proven in every case','Ischemic tubular injury and other causes are common.'),('The graft can never recover','Recovery is possible.'),('No further evaluation is needed once the label is assigned','Obstruction, vascular problems, rejection and other causes still need assessment.')],
 'A functional label is not an etiology', '**Dialysis in the first week is a common research definition of DGF.**',['Dialysis decisions can vary, so the definition has limitations.','Ischemia-reperfusion injury is a frequent mechanism.'], '**Evaluate persistent dysfunction systematically.**',['Use imaging, drug levels and biopsy when appropriate.','Provide KRT and immunosuppression according to the transplant plan.'],[['DGF','Early functional outcome'],['Frequent cause','Ischemic tubular injury'],['Necessary step','Exclude treatable alternatives']],[TR,EA],'clinical_scenario')
q('Immediately after transplant, abrupt anuria and graft-region pain develop. What is the first priority?', 'Urgent assessment for vascular compromise or obstruction, including Doppler imaging and surgical review',[
 ('Empiric prolonged steroid treatment before checking graft perfusion','A surgical emergency could be missed.'),('Assume chronic rejection','The timing is incompatible with a chronic-only explanation.'),('Wait several days for spontaneous recovery without assessment','Delay can sacrifice a salvageable graft.')],
 'Early graft dysfunction has time-critical mechanical causes', '**Arterial or venous thrombosis and obstruction need prompt exclusion.**',['Volume and hemodynamics also require assessment.','The urgency depends on the timing and clinical findings.'], '**Use immediate imaging and transplant-team evaluation.**',['A biopsy is not the first substitute for checking perfusion in abrupt anuria.','Correct reversible circulatory causes in parallel.'],[['Abrupt anuria','Emergency'],['Initial imaging','Doppler/obstruction assessment'],['Team','Transplant surgical review']],[EA],'clinical_scenario')
q('Creatinine rises persistently in a transplant recipient after volume depletion, obstruction and excessive drug exposure have been assessed. What often provides the decisive etiological information?', 'Kidney allograft biopsy with appropriate ancillary studies',[
 ('Serum creatinine alone distinguishes all rejection types','It identifies dysfunction, not its cause.'),('Treat every unexplained rise as rejection without tissue whenever biopsy is feasible','Infection and toxicity may require opposite management.'),('Urine color alone','This is not a reliable etiological discriminator.')],
 'Dysfunction has immune and nonimmune causes', '**Biopsy can identify rejection, viral injury and recurrent or de novo disease.**',['Immunofluorescence, electron microscopy and viral staining may be needed.','Biopsy safety and urgency must be considered.'], '**Integrate tissue with antibody, viral and drug data.**',['Do not interpret one lesion in isolation.','Use the result to guide targeted treatment.'],[['Creatinine','Signals dysfunction'],['Biopsy','Defines injury pattern'],['Context','DSA, virus, exposure and imaging']],[TR,BA])
q('Interstitial inflammation and tubulitis in a transplant biopsy can support which diagnosis after relevant mimics are considered?', 'T-cell-mediated rejection',[
 ('Hyperacute antibody rejection as the necessary diagnosis','That has a different timing and vascular mechanism.'),('BK nephropathy is excluded solely because tubulitis is present','BK can mimic cellular rejection.'),('Normal graft histology','Inflammation and tubulitis require interpretation.')],
 'Banff categories require lesion context', '**T-cell-mediated rejection involves characteristic inflammatory injury.**',['Vascular lesions affect classification and severity.','Viral infection and other causes must be distinguished.'], '**Treat according to the classified process and response.**',['Corticosteroids are commonly used for acute cellular rejection.','Resistant or severe cases require specialist escalation and adherence review.'],[['Typical lesions','Interstitial inflammation/tubulitis'],['Mimic','BK viral injury'],['Assessment','Banff plus clinical context']],[BA,TR])
q('Which combination best supports active antibody-mediated rejection?', 'Compatible graft injury plus evidence of antibody-endothelial interaction and relevant donor-specific antibody or accepted diagnostic substitutes',[
 ('Donor-specific antibody alone regardless of tissue or clinical findings','Antibody positivity alone does not establish active tissue rejection.'),('Any isolated creatinine rise with no immunological or tissue assessment','This is nonspecific.'),('C4d staining alone always proves destructive rejection','C4d can occur in settings without the full rejection diagnosis.')],
 'Antibody-mediated rejection is an integrated diagnosis', '**Microvascular inflammation is one important injury pattern.**',['C4d and validated molecular evidence can contribute to the classification.','Current Banff criteria distinguish several antibody and microvascular phenotypes.'], '**Use the current diagnostic framework.**',['Consider infection and other causes of microvascular injury.','Treatment selection requires a transplant specialist and the activity/chronicity context.'],[['Injury','Compatible tissue findings'],['Interaction','C4d or other accepted evidence'],['Immunology','DSA or accepted substitutes']],[BA])
q('A graft biopsy has microvascular inflammation but both circulating DSA and C4d are negative. Which statement reflects the updated Banff framework?', 'This can be classified as a distinct MVI, DSA-negative and C4d-negative phenotype requiring further etiological assessment',[
 ('Every case is automatically definite antibody-mediated rejection','The updated framework separates this phenotype.'),('Negative C4d excludes every form of antibody-mediated rejection','C4d-negative AMR can occur with other supporting evidence.'),('The tissue findings must be ignored if DSA is negative','They can remain clinically meaningful.')],
 'Microvascular inflammation is not synonymous with one mechanism', '**Banff 2022 introduced explicit categories for diagnostically incomplete or distinct phenotypes.**',['Alternative immune and nonimmune mechanisms require consideration.','Assay limits and the full biopsy pattern matter.'], '**Avoid both overdiagnosis and dismissal.**',['Review the current reference guide.','Follow function and integrate the complete immunological evaluation.'],[['MVI','Tissue injury pattern'],['DSA/C4d negative','Distinct classified phenotype'],['Next step','Integrated etiological assessment']],[BA])
q('An allograft biopsy shows interstitial fibrosis and tubular atrophy. What is the most accurate interpretation?', 'A chronic injury pattern that requires identification of its cause',[
 ('Proof that all injury is caused by calcineurin inhibitors','Rejection, recurrent disease, ischemia and other causes can produce scarring.'),('Proof of active rejection requiring identical treatment in every case','Activity and mechanism need separate assessment.'),('A finding with no possible prognostic relevance','Chronic scarring can affect graft function and prognosis.')],
 'IFTA is a description rather than a complete etiology', '**Chronic injury can result from several overlapping processes.**',['Inflammation, vascular and glomerular lesions refine interpretation.','Clinical course and prior biopsies can help.'], '**Target reversible contributors where present.**',['Review blood pressure, proteinuria, adherence and exposure.','Avoid assuming that reducing immunosuppression is always beneficial.'],[['IFTA','Chronic structural injury'],['Causes','Immune and nonimmune'],['Management','Etiology and reversible factors']],[TR,BA])
q('Tacrolimus exposure rises and graft function declines. Which acute renal effect is characteristic of calcineurin inhibitor toxicity?', 'Renal vasoconstriction with a potentially reversible fall in GFR',[
 ('An obligatory irreversible complete renal artery thrombosis','This is not the usual pharmacological mechanism.'),('Selective protection against hyperkalemia in every patient','CNIs can promote hyperkalemia.'),('A diagnosis established solely by any fibrosis on biopsy','Chronic lesions are not fully specific.')],
 'Acute exposure effects differ from chronic structural injury', '**Tacrolimus and cyclosporine can alter renal vascular tone.**',['Neurotoxicity, hypertension and metabolic effects may coexist.','A high trough supports exposure concern but does not exclude concurrent rejection or other injury.'], '**Review levels, interactions and timing.**',['Adjust therapy with the transplant team.','Use biopsy when the cause remains uncertain.'],[['Acute effect','Vasoconstriction'],['Exposure assessment','Drug level and interactions'],['Persistent dysfunction','Evaluate alternative or additional causes']],[TR,EA],'clinical_scenario')
q('A stable tacrolimus-treated recipient develops tremor and rising creatinine after starting clarithromycin. What is the most likely interaction?', 'Inhibition of tacrolimus metabolism causing increased exposure',[
 ('Strong induction of metabolism causing an immediate low level','Clarithromycin generally inhibits CYP3A-related metabolism.'),('No clinically meaningful interaction is expected','The interaction can be substantial.'),('Direct proof of acute cellular rejection without a drug-level check','The exposure history calls for urgent interaction assessment.')],
 'A new prescription can destabilize a narrow therapeutic range', '**Macrolides and azole antifungals can increase calcineurin inhibitor exposure.**',['Rifampicin can lower exposure through induction.','Other medications and food interactions can also matter.'], '**Check levels and coordinate regimen adjustment promptly.**',['Do not abruptly abandon immunosuppression without specialist advice.','Choose a suitable alternative antimicrobial when possible.'],[['Inhibitor','Can increase tacrolimus'],['Inducer','Can decrease tacrolimus'],['Response','Level and regimen review']],[TR,EA],'clinical_scenario')
